                            domain[2] - 0.1 * (domain[2] - domain[1]), length.out = 3)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      initial_points <- c(-1, 0, 1)
    } else if (is.infinite(domain[1])) {
      initial_points <- c(domain[2] - 2, domain[2] - 1, domain[2])
    } else {
      initial_points <- c(domain[1], domain[1] + 1, domain[1] + 2)
    }
  }

  initial_points <- sort(unique(initial_points))
  if (length(initial_points) < 2) {
    stop("At least 2 unique initial points are required.")
  }

  k <- length(initial_points)
  x <- initial_points
  h <- sapply(x, f_log)
  if (any(!is.finite(h))) {
    stop("Density evaluated to zero or non-finite value at initial points.")
