  s <- sapply(x, function(xi) h_prime(f_log, xi))

  for (i in 1:(k - 1)) {
    if (s[i] <= s[i+1]) {
      stop("Density is not log-concave: slopes at initial points are not strictly decreasing.")
    }
  }

  samples <- numeric(n)
  count <- 0
  max_iterations <- n * 100
  iter <- 0

  while (count < n && iter < max_iterations) {
    iter <- iter + 1
    k_curr <- length(x)
    z <- numeric(k_curr + 1)
    z[1] <- domain[1]
    z[k_curr + 1] <- domain[2]

    for (i in 1:(k_curr - 1)) {
      num <- h[i+1] - h[i] - s[i+1]*x[i+1] + s[i]*x[i]
      den <- s[i] - s[i+1]
      if (abs(den) < 1e-12) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      } else {
        z[i+1] <- num / den
      }
      if (is.na(z[i+1]) || z[i+1] <= x[i] || z[i+1] >= x[i+1]) {
