        stop("Density is not log-concave: slopes are not strictly decreasing after adding abscissa.")
      }
    }

    if (accepted) {
      count <- count + 1
      samples[count] <- x_star
    }
  }

  if (count < n) {
    warning("Maximum iterations reached before collecting all samples.")
    samples <- samples[1:count]
  }

  return(samples)
}

