# Adaptive Rejection Sampling (ARS) in R
# Based on Gilks & Wild (1992)

h_prime <- function(f_log, x, eps = 1e-4) {
  val1 <- f_log(x + eps)
  val2 <- f_log(x - eps)
  if (!is.finite(val1) || !is.finite(val2)) return(0)
  (val1 - val2) / (2 * eps)
}

validate_ars_inputs <- function(density_function, domain, n) {
  if (!is.function(density_function)) {
    stop("density_function must be a valid R function.")
  }
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2 with domain[1] < domain[2].")
  }
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n != round(n)) {
    stop("n must be a positive integer.")
  }
}

