ars <- function(density_function, domain, n = 1000, initial_points = NULL) {
  validate_ars_inputs(density_function, domain, n)

  f_log <- function(x) {
    res <- density_function(x)
    res[is.na(res)] <- 0
    res[res < 0] <- 0
    res[res == 0] <- 1e-300
    log_res <- log(res)
    log_res[x < domain[1] | x > domain[2]] <- -Inf
    return(log_res)
  }

  if (is.null(initial_points)) {
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      initial_points <- seq(domain[1] + 0.1 * (domain[2] - domain[1]), 
                            domain[2] - 0.1 * (domain[2] - domain[1]), length.out = 4)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      initial_points <- c(-2, -1, 0, 1, 2)
    } else if (is.infinite(domain[1])) {
      initial_points <- c(domain[2] - 3, domain[2] - 2, domain[2] - 1, domain[2])
    } else {
      # Semi-infinite [L, Inf)
      initial_points <- c(domain[1] + 0.1, domain[1] + 1.0, domain[1] + 2.0, domain[1] + 3.0)
    }
  }

  initial_points <- sort(unique(initial_points))
  # Ensure all initial points are within domain
  initial_points <- initial_points[initial_points >= domain[1] & initial_points <= domain[2]]
  if (length(initial_points) < 2) {
    initial_points <- c(domain[1] + 0.1, domain[1] + 1.0, domain[1] + 2.0)
  }

  k <- length(initial_points)
  x <- initial_points
  h <- sapply(x, f_log)
  if (any(!is.finite(h))) {
    stop("Density evaluated to zero or non-finite value at initial points.")
  }
  s <- sapply(x, function(xi) h_prime(f_log, xi))

  for (i in 1:(k - 1)) {
    if (s[i] < s[i+1] - 1e-5) {
      stop("Density is not log-concave: slopes are not monotonically decreasing.")
    }
  }

  samples <- numeric(n)
  count <- 0
  max_iterations <- n * 200
  iter <- 0

  while (count < n && iter < max_iterations) {
    iter <- iter + 1
    k_curr <- length(x)
    z <- numeric(k_curr + 1)
    z[1] <- domain[1]
    z[k_curr + 1] <- domain[2]

    for (i in 1:(k_curr - 1)) {
      num <- h[i+1] - h[i] - s[i+1]*x[i+1] + s[i]*x[i]
      den <- s[i] - s[i+1]
      if (abs(den) < 1e-12) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      } else {
        z[i+1] <- num / den
      }
      if (is.na(z[i+1]) || z[i+1] <= x[i] || z[i+1] >= x[i+1]) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      }
    }

    log_weights <- numeric(k_curr)
    for (i in 1:k_curr) {
      hi <- h[i]
      si <- s[i]
      zi_left <- z[i]
      zi_right <- z[i+1]

      if (!is.finite(zi_left) || !is.finite(zi_right)) {
        log_weights[i] <- -Inf
        next
      }

      if (abs(si) < 1e-12) {
        log_weights[i] <- hi + log(max(1e-300, zi_right - zi_left))
      } else {
        term1 <- hi - si * x[i]
        diff_exp <- exp(si * zi_right) - exp(si * zi_left)
        if (si < 0) {
          diff_exp <- exp(si * zi_left) * (exp(si * (zi_right - zi_left)) - 1)
        }
        term2 <- log(max(1e-300, abs(diff_exp)))
        log_weights[i] <- term1 + term2 - log(abs(si))
      }
    }

    if (all(!is.finite(log_weights)) || all(log_weights == -Inf)) {
      next
    }

    max_lw <- max(log_weights[is.finite(log_weights)])
    weights <- exp(log_weights - max_lw)
    weights[!is.finite(weights)] <- 0
    sum_w <- sum(weights)
    if (sum_w == 0) next
    prob <- weights / sum_w

    chosen_interval <- sample.int(k_curr, 1, prob = prob)

    i <- chosen_interval
    zi_l <- z[i]
    zi_r <- z[i+1]
    hi <- h[i]
    si <- s[i]

    u_unif <- runif(1)
    if (abs(si) < 1e-12) {
      x_star <- zi_l + u_unif * (zi_r - zi_l)
    } else {
      term_l <- si * (zi_l - x[i])
      term_r <- si * (zi_r - x[i])
      diff_er <- exp(term_r) - exp(term_l)
      if (abs(diff_er) < 1e-300) {
        x_star <- (zi_l + zi_r) / 2
      } else {
        val <- term_l + log(max(1e-300, u_unif * diff_er + exp(term_l)))
        x_star <- x[i] + val / si
      }
    }

    if (!is.finite(x_star) || x_star < domain[1] || x_star > domain[2]) {
      next
    }

    h_star <- f_log(x_star)
    if (!is.finite(h_star)) {
      next
    }

    interval_idx <- findInterval(x_star, z, rightmost.closed = TRUE)
    interval_idx <- max(1, min(interval_idx, k_curr))
    u_star <- h[interval_idx] + s[interval_idx] * (x_star - x[interval_idx])

    if (h_star > u_star + 1e-5) {
      stop("Density is not log-concave: evaluated log-density exceeds upper envelope.")
    }

    l_star <- -Inf
    if (x_star >= x[1] && x_star <= x[k]) {
      j <- max(which(x <= x_star))
      if (j < k_curr || (j == k_curr && x_star == x[k])) {
        if (j == k_curr) j <- k_curr - 1
        l_star <- h[j] + (h[j+1] - h[j]) / (x[j+1] - x[j]) * (x_star - x[j])
      }
    }

    v <- runif(1)
    accepted <- FALSE
    if (is.finite(l_star) && v <= exp(l_star - u_star)) {
      accepted <- TRUE
    } else if (v <= exp(h_star - u_star)) {
      accepted <- TRUE
    }

    s_star <- h_prime(f_log, x_star)
    insert_idx <- findInterval(x_star, x) + 1
    x <- c(x[1:(insert_idx-1)], x_star, x[insert_idx:k_curr])
    h <- c(h[1:(insert_idx-1)], h_star, h[insert_idx:k_curr])
    s <- c(s[1:(insert_idx-1)], s_star, s[insert_idx:k_curr])
    k_curr <- length(x)

    for (i in 1:(k_curr - 1)) {
      if (s[i] < s[i+1] - 1e-5) {
        stop("Density is not log-concave: slopes are not monotonically decreasing after adding abscissa.")
      }
    }

    if (accepted) {
      count <- count + 1
      samples[count] <- x_star
    }
  }

  if (count < n) {
    warning("Maximum iterations reached before collecting all samples.")
    samples <- samples[1:count]
  }

  return(samples)
}

