      cat("INPUT_VALIDATION_TEST: FAIL\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("INPUT_VALIDATION_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  tryCatch({
    cauchy_density <- function(x) dcauchy(x)
    res <- tryCatch(ars(cauchy_density, domain = c(-5, 5), n = 100), error = function(e) "CAUGHT")
    if (res == "CAUGHT") {
      cat("NON_LOG_CONCAVE_TEST: Mean = NA, SD = NA\n")
      cat("NON_LOG_CONCAVE_TEST: PASS\n")
    } else {
      cat("NON_LOG_CONCAVE_TEST: FAIL\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("NON_LOG_CONCAVE_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  cat("\nOverall Test Status: ")
  if (all_passed) {
    cat("ALL TESTS PASSED\n")
  } else {
    cat("SOME TESTS FAILED\n")
  }
}
