    stop("n must be a positive integer.")
  }
}

ars <- function(density_function, domain, n = 1000, initial_points = NULL) {
  validate_ars_inputs(density_function, domain, n)

  f_log <- function(x) {
    res <- density_function(x)
    res[is.na(res)] <- 0
    res[res < 0] <- 0
    res[res == 0] <- 1e-300
    log_res <- log(res)
    log_res[x < domain[1] | x > domain[2]] <- -Inf
    return(log_res)
  }

  if (is.null(initial_points)) {
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      initial_points <- seq(domain[1] + 0.1 * (domain[2] - domain[1]), 
                            domain[2] - 0.1 * (domain[2] - domain[1]), length.out = 4)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      initial_points <- c(-2, -1, 0, 1, 2)
    } else if (is.infinite(domain[1])) {
      initial_points <- c(domain[2] - 3, domain[2] - 2, domain[2] - 1, domain[2])
    } else {
      initial_points <- c(domain[1] + 0.2, domain[1] + 1.0, domain[1] + 2.5, domain[1] + 4.0)
    }
  }

  initial_points <- sort(unique(initial_points))
  initial_points <- initial_points[initial_points >= domain[1] & initial_points <= domain[2]]
  initial_points <- sort(unique(initial_points))
  if (length(initial_points) < 2) {
    initial_points <- c(domain[1] + 0.2, domain[1] + 1.0, domain[1] + 2.0)
  }

  k <- length(initial_points)
  x <- initial_points
  h <- sapply(x, f_log)
  if (any(!is.finite(h))) {
    stop("Density evaluated to zero or non-finite value at initial points.")
  }
  s <- sapply(x, function(xi) h_prime(f_log, xi))

  for (i in 1:(k - 1)) {
    if (s[i] < s[i+1] - 1e-5) {
      stop("Density is not log-concave: slopes are not monotonically decreasing.")
    }
  }

  samples <- numeric(n)
  count <- 0
  max_iterations <- n * 200
  iter <- 0

  while (count < n && iter < max_iterations) {
    iter <- iter + 1
    k_curr <- length(x)
    z <- numeric(k_curr + 1)
    z[1] <- domain[1]
    z[k_curr + 1] <- domain[2]

    for (i in 1:(k_curr - 1)) {
      num <- h[i+1] - h[i] - s[i+1]*x[i+1] + s[i]*x[i]
      den <- s[i] - s[i+1]
      if (abs(den) < 1e-12) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      } else {
        z[i+1] <- num / den
      }
      if (is.na(z[i+1]) || z[i+1] <= x[i] || z[i+1] >= x[i+1]) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      }
    }

