    if (is.finite(domain[1]) && is.finite(domain[2])) {
      initial_points <- seq(domain[1] + 0.2*(domain[2]-domain[1]), domain[2] - 0.2*(domain[2]-domain[1]), length.out = 3)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      initial_points <- c(-1.5, 0, 1.5)
    } else if (is.infinite(domain[1])) {
      initial_points <- c(domain[2] - 2, domain[2] - 1, domain[2])
    } else {
      initial_points <- c(domain[1] + 0.5, domain[1] + 1.5, domain[1] + 2.5)
    }
  }

  x <- sort(unique(initial_points))
  x <- x[x > domain[1] & x < domain[2]]
  if (length(x) < 2) {
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      x <- seq(domain[1] + 0.1, domain[2] - 0.1, length.out = 3)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      x <- c(-1, 0, 1)
    } else if (is.infinite(domain[1])) {
      x <- c(domain[2] - 3, domain[2] - 2, domain[2] - 1)
    } else {
      x <- c(domain[1] + 0.1, domain[1] + 1.0, domain[1] + 2.0)
    }
  }

  h <- sapply(x, f_log)
  s <- sapply(x, function(xi) h_prime(f_log, xi))

  # Check initial log-concavity
  for (i in 1:(length(x)-1)) {
    if (s[i] < s[i+1] - 1e-4) {
      stop("Density is not log-concave: initial slopes not decreasing.")
    }
  }

  samples <- numeric(n)
  count <- 0
  max_iter <- n * 100
  iter <- 0

  while (count < n && iter < max_iter) {
    iter <- iter + 1
    k <- length(x)

    # Compute intersection points z
    z <- numeric(k + 1)
    z[1] <- domain[1]
    z[k + 1] <- domain[2]

    for (i in 1:(k - 1)) {
      den <- s[i] - s[i+1]
      if (abs(den) < 1e-10) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      } else {
        val <- (h[i+1] - h[i] - s[i+1]*x[i+1] + s[i]*x[i]) / den
        if (val > x[i] && val < x[i+1]) {
