        } else {
          z[i+1] <- (x[i] + x[i+1]) / 2
        }
      }
    }

    # Ensure z is strictly sorted
    z <- sort(unique(z))
    if (length(z) != k + 1) {
      # Fallback distinct z
      z <- c(domain[1], x[1:(k-1)] + diff(x)/2, domain[2])
      z <- sort(z)
    }

    # Calculate upper envelope weights for intervals [z[i], z[i+1]]
    log_w <- numeric(k)
    for (i in 1:k) {
      zi_l <- z[i]
      zi_r <- z[i+1]
      hi <- h[i]
      si <- s[i]
      if (!is.finite(zi_l) || !is.finite(zi_r) || zi_l >= zi_r) {
        log_w[i] <- -Inf
        next
      }
      if (abs(si) < 1e-10) {
        log_w[i] <- hi + log(zi_r - zi_l)
      } else {
        term1 <- hi - si * x[i]
        diff_exp <- exp(si * zi_r) - exp(si * zi_l)
        if (si < 0) {
          diff_exp <- exp(si * zi_l) * (exp(si * (zi_r - zi_l)) - 1)
        }
        log_w[i] <- term1 + log(max(1e-300, abs(diff_exp))) - log(abs(si))
      }
    }

    if (all(!is.finite(log_w)) || all(log_w == -Inf)) next

    max_lw <- max(log_w[is.finite(log_w)])
    w <- exp(log_w - max_lw)
    if (sum(w) == 0) next
    prob <- w / sum(w)

    chosen_int <- sample.int(k, 1, prob = prob)
    i <- chosen_int
    zi_l <- z[i]
    zi_r <- z[i+1]
    hi <- h[i]
    si <- s[i]

    # Sample x_star from exponential on [zi_l, zi_r]
    u <- runif(1)
    if (abs(si) < 1e-10) {
      x_star <- zi_l + u * (zi_r - zi_l)
    } else {
      term_l <- si * (zi_l - x[i])
      term_r <- si * (zi_r - x[i])
      diff_er <- exp(term_r) - exp(term_l)
      if (abs(diff_er) < 1e-300) {
        x_star <- (zi_l + zi_r) / 2
      } else {
        val <- term_l + log(max(1e-300, u * diff_er + exp(term_l)))
        x_star <- x[i] + val / si
      }
    }

    if (!is.finite(x_star) || x_star < domain[1] || x_star > domain[2]) next

    h_star <- f_log(x_star)
    if (!is.finite(h_star)) next

    # Upper envelope value at x_star
    interval_idx <- findInterval(x_star, z, rightmost.closed = TRUE)
    interval_idx <- max(1, min(interval_idx, k))
    u_star <- h[interval_idx] + s[interval_idx] * (x_star - x[interval_idx])

    if (h_star > u_star + 1e-4) {
      stop("Density is not log-concave: h(x*) > u(x*).")
    }

    # Lower envelope value at x_star
    l_star <- -Inf
    if (x_star >= x[1] && x_star <= x[k]) {
      j <- max(which(x <= x_star))
      if (j < k) {
        l_star <- h[j] + (h[j+1] - h[j]) / (x[j+1] - x[j]) * (x_star - x[j])
      }
    }

    v <- runif(1)
    accepted <- FALSE
    if (is.finite(l_star) && v <= exp(l_star - u_star)) {
      accepted <- TRUE
    } else if (v <= exp(h_star - u_star)) {
      accepted <- TRUE
    }

    # Update abscissae
    s_star <- h_prime(f_log, x_star)
    insert_pos <- findInterval(x_star, x) + 1
    x <- c(x[1:(insert_pos-1)], x_star, x[insert_pos:k])
    h <- c(h[1:(insert_pos-1)], h_star, h[insert_pos:k])
    s <- c(s[1:(insert_pos-1)], s_star, s[insert_pos:k])

    # Check slope monotonicity
    for (j in 1:(length(x) - 1)) {
      if (s[j] < s[j+1] - 1e-4) {
        stop("Density is not log-concave: slopes not decreasing after update.")
      }
    }

    if (accepted) {
      count <- count + 1
      samples[count] <- x_star
    }
  }

  if (count < n) {
    samples <- samples[1:count]
  }
  return(samples)
}

