h_prime <- function(f_log, x) {
  eps <- 1e-4
  (f_log(x + eps) - f_log(x - eps)) / (2 * eps)
}

validate_ars_inputs <- function(density_function, domain, n) {
  if (!is.function(density_function)) stop("density_function must be a function.")
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) stop("Invalid domain.")
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n != round(n)) stop("Invalid sample count n.")
}

ars <- function(density_function, domain, n = 1000, initial_points = NULL) {
  validate_ars_inputs(density_function, domain, n)

  f_log <- function(x) {
    sapply(x, function(xi) {
      if (!is.finite(xi) || xi < domain[1] || xi > domain[2]) return(-Inf)
      val <- density_function(xi)
      if (is.na(val) || val <= 0 || !is.finite(val)) return(-Inf)
      log(val)
    })
  }

  if (is.null(initial_points)) {
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      initial_points <- seq(domain[1] + 0.2*(domain[2]-domain[1]), domain[2] - 0.2*(domain[2]-domain[1]), length.out = 3)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      initial_points <- c(-2, 0, 2)
    } else if (is.infinite(domain[1])) {
      initial_points <- c(domain[2] - 3, domain[2] - 2, domain[2] - 1)
    } else {
      initial_points <- c(domain[1] + 0.5, domain[1] + 1.5, domain[1] + 2.5)
    }
  }

  x <- sort(unique(initial_points))
  x <- x[x > domain[1] & x < domain[2]]
  if (length(x) < 2) {
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      x <- seq(domain[1] + 0.1, domain[2] - 0.1, length.out = 3)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      x <- c(-1.5, 0, 1.5)
    } else if (is.infinite(domain[1])) {
      x <- c(domain[2] - 3, domain[2] - 2, domain[2] - 1)
    } else {
      x <- c(domain[1] + 0.5, domain[1] + 1.5, domain[1] + 2.5)
    }
  }

  h <- sapply(x, f_log)
  s <- sapply(x, function(xi) h_prime(f_log, xi))

  samples <- numeric(n)
  count <- 0
  max_iter <- n * 300
  iter <- 0

  while (count < n && iter < max_iter) {
    iter <- iter + 1
    k <- length(x)

    z <- numeric(k + 1)
    z[1] <- domain[1]
    z[k + 1] <- domain[2]

    for (i in 1:(k - 1)) {
      den <- s[i] - s[i+1]
      if (abs(den) < 1e-8) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      } else {
        val <- (h[i+1] - h[i] - s[i+1]*x[i+1] + s[i]*x[i]) / den
        if (is.finite(val) && val > x[i] && val < x[i+1]) {
          z[i+1] <- val
        } else {
          z[i+1] <- (x[i] + x[i+1]) / 2
        }
      }
    }

    z[is.na(z) | !is.finite(z)] <- (x[1] + x[k]) / 2
    z <- sort(unique(z))
    if (length(z) != k + 1) {
      z <- c(domain[1], seq(min(x), max(x), length.out = k - 1), domain[2])
      z[is.na(z) | !is.finite(z)] <- 0
      z <- sort(unique(z))
      if (length(z) != k + 1) {
        z <- seq(domain[1], domain[2], length.out = k + 1)
      }
    }

    log_w <- numeric(k)
    for (i in 1:k) {
      zi_l <- z[i]
      zi_r <- z[i+1]
      hi <- h[i]
      si <- s[i]
      if (!is.finite(zi_l) || !is.finite(zi_r) || zi_l >= zi_r) {
        log_w[i] <- -Inf
        next
      }
      if (abs(si) < 1e-8) {
        log_w[i] <- hi + log(zi_r - zi_l)
      } else {
        term1 <- hi - si * x[i]
        diff_exp <- exp(si * zi_r) - exp(si * zi_l)
        if (si < 0) {
          diff_exp <- exp(si * zi_l) * (exp(si * (zi_r - zi_l)) - 1)
        }
        log_w[i] <- term1 + log(max(1e-300, abs(diff_exp))) - log(abs(si))
      }
    }

    if (all(!is.finite(log_w)) || all(log_w == -Inf)) next

    max_lw <- max(log_w[is.finite(log_w)])
    w <- exp(log_w - max_lw)
    if (sum(w) == 0) next
    prob <- w / sum(w)

    chosen_int <- sample.int(k, 1, prob = prob)
    i <- chosen_int
    zi_l <- z[i]
    zi_r <- z[i+1]
    hi <- h[i]
    si <- s[i]

    u <- runif(1)
    if (abs(si) < 1e-8) {
      x_star <- zi_l + u * (zi_r - zi_l)
    } else {
      term_l <- si * (zi_l - x[i])
      term_r <- si * (zi_r - x[i])
      diff_er <- exp(term_r) - exp(term_l)
      if (abs(diff_er) < 1e-300) {
        x_star <- (zi_l + zi_r) / 2
      } else {
        val <- term_l + log(max(1e-300, u * diff_er + exp(term_l)))
        x_star <- x[i] + val / si
      }
    }

    if (!is.finite(x_star) || x_star < domain[1] || x_star > domain[2]) next

    h_star <- f_log(x_star)
    if (!is.finite(h_star)) next

    interval_idx <- findInterval(x_star, z, rightmost.closed = TRUE)
    interval_idx <- max(1, min(interval_idx, k))
    u_star <- h[interval_idx] + s[interval_idx] * (x_star - x[interval_idx])

    if (h_star > u_star + 1e-2) {
      stop("Density is not log-concave: h(x*) > u(x*).")
    }

    l_star <- -Inf
    if (x_star >= x[1] && x_star <= x[k]) {
      j <- max(which(x <= x_star))
      if (j < k) {
        l_star <- h[j] + (h[j+1] - h[j]) / (x[j+1] - x[j]) * (x_star - x[j])
      }
    }

    v <- runif(1)
    accepted <- FALSE
    if (is.finite(l_star) && v <= exp(l_star - u_star)) {
      accepted <- TRUE
    } else if (v <= exp(h_star - u_star)) {
      accepted <- TRUE
    }

    s_star <- h_prime(f_log, x_star)
    insert_pos <- findInterval(x_star, x) + 1
    x <- c(x[1:(insert_pos-1)], x_star, x[insert_pos:k])
    h <- c(h[1:(insert_pos-1)], h_star, h[insert_pos:k])
    s <- c(s[1:(insert_pos-1)], s_star, s[insert_pos:k])

    if (accepted) {
      count <- count + 1
      samples[count] <- x_star
    }
  }

  if (count < n) {
    samples <- samples[1:count]
  }
  return(samples)
}

test <- function() {
  cat("Running Adaptive Rejection Sampling Tests...\n\n")
  all_passed <- TRUE

  tryCatch({
    set.seed(42)
    samples_norm <- ars(function(x) dnorm(x), domain = c(-Inf, Inf), n = 1000)
    mean_val <- mean(samples_norm)
    sd_val <- sd(samples_norm)
    cat(sprintf("NORMAL_DISTRIBUTION_TEST: Mean = %.4f, SD = %.4f\n", mean_val, sd_val))
    writeLines(as.character(samples_norm), "/app/normal_samples.txt")
    if (abs(mean_val) < 0.2 && abs(sd_val - 1.0) < 0.25 && length(samples_norm) == 1000) {
      cat("NORMAL_DISTRIBUTION_TEST: PASS\n")
    } else {
      cat("NORMAL_DISTRIBUTION_TEST: FAIL\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("NORMAL_DISTRIBUTION_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  tryCatch({
    set.seed(42)
    samples_exp <- ars(function(x) dexp(x, rate = 1), domain = c(0.01, 20), n = 1000, initial_points = c(0.5, 1.5, 3.0))
    mean_val <- mean(samples_exp)
    sd_val <- sd(samples_exp)
    cat(sprintf("EXPONENTIAL_DISTRIBUTION_TEST: Mean = %.4f, SD = %.4f\n", mean_val, sd_val))
    writeLines(as.character(samples_exp), "/app/exponential_samples.txt")
    if (abs(mean_val - 1.0) < 0.3 && abs(sd_val - 1.0) < 0.3 && length(samples_exp) == 1000) {
      cat("EXPONENTIAL_DISTRIBUTION_TEST: PASS\n")
    } else {
      cat("EXPONENTIAL_DISTRIBUTION_TEST: FAIL\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("EXPONENTIAL_DISTRIBUTION_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  tryCatch({
    res <- tryCatch(ars(function(x) dnorm(x), domain = c(-Inf, Inf), n = -10), error = function(e) "CAUGHT")
    res2 <- tryCatch(ars(function(x) dnorm(x), domain = c(5, 1), n = 100), error = function(e) "CAUGHT")
    if (res == "CAUGHT" && res2 == "CAUGHT") {
      cat("INPUT_VALIDATION_TEST: Mean = NA, SD = NA\n")
      cat("INPUT_VALIDATION_TEST: PASS\n")
    } else {
      cat("INPUT_VALIDATION_TEST: FAIL\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("INPUT_VALIDATION_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  tryCatch({
    cauchy_density <- function(x) dcauchy(x)
    res <- tryCatch(ars(cauchy_density, domain = c(-5, 5), n = 100), error = function(e) "CAUGHT")
    if (res == "CAUGHT") {
      cat("NON_LOG_CONCAVE_TEST: Mean = NA, SD = NA\n")
      cat("NON_LOG_CONCAVE_TEST: PASS\n")
    } else {
      cat("NON_LOG_CONCAVE_TEST: FAIL\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("NON_LOG_CONCAVE_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  cat("\nOverall Test Status: ")
  if (all_passed) {
    cat("ALL TESTS PASSED\n")
  } else {
    cat("SOME TESTS FAILED\n")
  }
}
EOF
Rscript -e 'source("/app/ars.R"); test()'

