      x <- seq(domain[1] + 0.1, domain[2] - 0.1, length.out = 3)
    } else if (is.infinite(domain[1]) && is.infinite(domain[2])) {
      x <- c(-1.5, 0, 1.5)
    } else if (is.infinite(domain[1])) {
      x <- c(domain[2] - 3, domain[2] - 2, domain[2] - 1)
    } else {
      x <- c(domain[1] + 0.5, domain[1] + 1.5, domain[1] + 2.5)
    }
  }

  h <- sapply(x, f_log)
  s <- sapply(x, function(xi) h_prime(f_log, xi))

  samples <- numeric(n)
  count <- 0
  max_iter <- n * 300
  iter <- 0

  while (count < n && iter < max_iter) {
    iter <- iter + 1
    k <- length(x)

    z <- numeric(k + 1)
    z[1] <- domain[1]
    z[k + 1] <- domain[2]

    for (i in 1:(k - 1)) {
      den <- s[i] - s[i+1]
      if (abs(den) < 1e-8) {
        z[i+1] <- (x[i] + x[i+1]) / 2
      } else {
        val <- (h[i+1] - h[i] - s[i+1]*x[i+1] + s[i]*x[i]) / den
        if (is.finite(val) && val > x[i] && val < x[i+1]) {
          z[i+1] <- val
        } else {
          z[i+1] <- (x[i] + x[i+1]) / 2
        }
      }
    }

    z[is.na(z) | !is.finite(z)] <- (x[1] + x[k]) / 2
    z <- sort(unique(z))
    if (length(z) != k + 1) {
      d_l <- ifelse(is.finite(domain[1]), domain[1], min(x) - 1)
      d_r <- ifelse(is.finite(domain[2]), domain[2], max(x) + 1)
      z <- c(d_l, seq(min(x), max(x), length.out = k - 1), d_r)
      z[is.na(z) | !is.finite(z)] <- 0
      z <- sort(unique(z))
      if (length(z) != k + 1) {
        z <- seq(min(x) - 1, max(x) + 1, length.out = k + 1)
      }
    }

    log_w <- numeric(k)
    for (i in 1:k) {
      zi_l <- z[i]
      zi_r <- z[i+1]
      hi <- h[i]
      si <- s[i]
      if (!is.finite(zi_l) || !is.finite(zi_r) || zi_l >= zi_r) {
        log_w[i] <- -Inf
        next
      }
      if (abs(si) < 1e-8) {
        log_w[i] <- hi + log(zi_r - zi_l)
