    }

    if (all(!is.finite(log_w)) || all(log_w == -Inf)) next

    max_lw <- max(log_w[is.finite(log_w)])
    w <- exp(log_w - max_lw)
    if (sum(w) == 0) next
    prob <- w / sum(w)

    chosen_int <- sample.int(k, 1, prob = prob)
    i <- chosen_int
    zi_l <- z[i]
    zi_r <- z[i+1]
    hi <- h[i]
    si <- s[i]

    u <- runif(1)
    if (abs(si) < 1e-8) {
      x_star <- zi_l + u * (zi_r - zi_l)
